export const PRIVACY_PAGE: LegalPage = { title: "DBD Presence — privacy notice", body: "<p>DBD Presence is an unofficial, fan-made Discord Rich Presence companion for Dead by Daylight. It is not affiliated with or endorsed by Behaviour Interactive or Discord.</p>\n<h2>Using the app</h2>\n<p>You need to sign in with Discord to use DBD Presence. Until you have signed in (and, while access is by invitation, entered an invite code), the app sends nothing to Discord and shows only the sign-in screen. Once you are in, your chosen status text goes only to the Discord app on the same PC, and it keeps working if the DBD Presence service cannot be reached; it stops only if the service owner withdraws your access. There is no telemetry and no crash reporting.</p>\n<p>A licence file, signed by the service and encrypted for your Windows account, is kept on your PC. It proves that you signed in on this PC and lets the app keep working offline. Signing out or deleting your account removes it.</p>\n<p><strong>Automatic detection</strong> is off unless you turn it on. When it is on, the app looks only at the Dead by Daylight window on your screen to recognise what is happening in the game. This happens on your PC. The pictures are never sent to the service or anyone else, and they are not saved unless you turn on test recording yourself, which shows where the files go and lets you delete them.</p>\n<h2>When you sign in</h2>\n<p>Signing in is required and uses Discord&#39;s sign-in page in your browser. While access is by invitation you also enter an invite code once; if the service owner opens DBD Presence to everyone, only the sign-in is needed. The service receives your Discord user ID and display name from Discord (scope <code>identify</code> only). It does not receive or keep your email address, and it does not show your avatar anywhere.</p>\n<p><strong>What the service stores</strong></p>\n<ul><li>your Discord user ID and display name;</li><li>the dates you joined and last used the service;</li><li>your account status (active or withdrawn) and whether you redeemed an invite code;</li><li>a public key for each PC you sign in on (the private key stays on that PC and cannot be exported);</li><li>session records (hashes of session tokens, never the tokens themselves).</li></ul>\n<p><strong>What it does not store:</strong> your email address, your IP address history, your game activity, or anything from the game.</p>\n<p><strong>What it can see:</strong> each daily check-in (licence refresh) shows the service your IP address for that request and updates your last-seen time. The IP address is used to handle the request and for rate limiting; it is not kept as a history.</p>\n<p><strong>Pictures on your Discord status</strong></p>\n<p>Discord can only show pictures that are online. When you save or import your own pictures (from a pack or your PC) while signed in, the app puts a copy of each on the DBD Presence service at an unlisted address, ready for your Discord status. Each person can store up to 60 MB. It is not listed or shared, but anyone who sees your status can see it. It is deleted when you remove it, delete your account, or the owner removes it; Discord may show a cached copy for a while, and backups keep it for up to 30 days.</p>\n<h2>Why it is used</h2>\n<ul><li>To provide the service you signed in for (sign-in, invites, synced packs): this is needed to provide the service you asked for (UK GDPR Article 6(1)(b)).</li><li>Security logs, rate limits and preventing misuse: our legitimate interest in keeping the service safe (Article 6(1)(f)).</li></ul>\n<h2>How long data is kept</h2>\n<ul><li>Accounts are kept until you delete them. Inactive accounts are deleted after 12 months.</li><li>Rate-limit counters: 24 hours.</li><li>Security and audit logs: 90 days. When you delete your account, user identifiers in those logs are pseudonymised.</li><li>Backups: database restore points are kept for 7 days and encrypted exports for 30 days. Deleted data can remain in backups until they expire.</li></ul>\n<h2>Your rights</h2>\n<p>You can delete your account at any time from the Account page in the app. You can ask for a copy of your data, or for correction, by emailing caylen_tucker@icloud.com; requests are answered within one month. You can also object to how your data is used. If you are unhappy with the answer, you can complain to the Information Commissioner&#39;s Office (ico.org.uk).</p>\n<h2>Processors</h2>\n<p>The service runs on Cloudflare, which acts as a processor. Cloudflare may handle data outside the UK; those transfers are covered by Cloudflare&#39;s data processing addendum, which uses the UK International Data Transfer Addendum to the EU standard contractual clauses. Content images are fetched by Discord&#39;s own servers, not by this app, and the app never loads images from the internet.</p>\n<h2>Who is responsible</h2>\n<p>The controller is Arcavale, which runs DBD Presence. Contact: caylen_tucker@icloud.com.</p>\n" };

export const TERMS_PAGE: LegalPage = { title: "DBD Presence — terms of use", body: "<p>These terms apply to everyone who uses DBD Presence. Using it needs a sign-in with Discord.</p>\n<h2>Who can use it</h2>\n<ul><li>You must be <strong>18 or over</strong>, because Dead by Daylight is rated for adults.</li><li>While the service is invite-only, you need an invite code. A code can be used <strong>once</strong>, and only by the Discord account that redeems it. Please don&#39;t share or sell codes.</li><li>Use of the service is personal to your Discord account. Don&#39;t let other people use your sign-in.</li></ul>\n<h2>What it is</h2>\n<ul><li>An <strong>unofficial fan-made app</strong>. It is not affiliated with or endorsed by Behaviour Interactive or Discord. Dead by Daylight is a trademark of Behaviour Interactive Inc.</li><li>It is <strong>free</strong>. It shows your Dead by Daylight activity on your Discord profile. It never reads the game&#39;s memory and never changes the game or its files. If you turn on automatic detection, it looks only at the game window on your screen, on your PC; those pictures are never sent anywhere.</li></ul>\n<h2>Your part</h2>\n<ul><li>Don&#39;t misuse the service. That means don&#39;t:<ul><li>try to get around invite codes, sign-in or limits;</li><li>overload the service;</li><li>copy or redistribute the app, its image packs or its content, unless the owner allows it.</li></ul></li><li>Anything you put on your Discord profile through the app must follow Discord&#39;s own rules.</li><li>If you import a NightLight pack or use your own images, you must have the right to use them.</li></ul>\n<h2>Images and game art</h2>\n<ul><li>Some images come from Behaviour Interactive&#39;s games and are used as non-commercial fan content. They may be removed at any time, for example if the rights holder asks. When an image is removed, your status simply shows no picture.</li></ul>\n<h2>Your pictures</h2>\n<ul><li>Only use pictures you made or are allowed to use, and nothing offensive, hateful, sexual or illegal. The owner may remove any picture. To report one, email caylen_tucker@icloud.com.</li></ul>\n<h2>Access can change</h2>\n<ul><li>The owner can end or suspend access, for example for misuse or shared codes. The owner can also change these terms or switch the service off. Important changes are announced in the app.</li><li>If you have been offline, your Discord status keeps working. Access is only cut off when a signed revocation arrives from the service.</li></ul>\n<h2>No warranty</h2>\n<ul><li>The app and the service are provided <strong>as they are</strong>, with no guarantee that they will always work. As far as the law allows, the owner is not liable for any loss arising from their use. Nothing in these terms limits your statutory rights as a consumer in the UK.</li></ul>\n<h2>Privacy</h2>\n<ul><li>What is stored and why is explained in the privacy notice, which comes with the app.</li></ul>\n<h2>Contact and law</h2>\n<ul><li>Contact: caylen_tucker@icloud.com. The service is run by Arcavale.</li><li>These terms are governed by the law of England and Wales.</li></ul>\n" };
